/*
 *	Start with some simple X versus S tracking
 *	to clean up the local accesses
 */

uint16_t x_fpoff;
unsigned x_fprel;
uint8_t a_val;
uint8_t b_val;
unsigned a_valid;
unsigned b_valid;
unsigned d_valid;
static struct node d_node;

void invalidate_all(void)
{
	x_fprel = 0;
	a_valid = 0;
	b_valid = 0;
	d_valid = 0;
}

void invalidate_x(void)
{
	x_fprel = 0;
}

void invalidate_a(void)
{
	a_valid = 0;
}

void invalidate_b(void)
{
	b_valid = 0;
}

void invalidate_d(void)
{
	d_valid = 0;
}

void invalidate_work(void)
{
	a_valid = 0;
	b_valid = 0;
	d_valid = 0;
}

void invalidate_mem(void)
{
	/* If memory changes it might be an alias to the value cached in AB */
	switch(d_node.op) {
	case T_LREF:
	case T_LBREF:
	case T_NREF:
		d_valid = 0;
	}
}

void set_d_node(struct node *n)
{
	memcpy(&d_node, n, sizeof(struct node));
	switch(d_node.op) {
	case T_LSTORE:
		d_node.op = T_LREF;
		break;
	case T_LBSTORE:
		d_node.op = T_LBREF;
		break;
	case T_NSTORE:
		d_node.op = T_NREF;
		break;
	case T_RSTORE:
		d_node.op = T_RREF;
		break;
	case T_NREF:
	case T_LBREF:
	case T_LREF:
	case T_NAME:
	case T_LABEL:
	case T_LOCAL:
	case T_ARGUMENT:
		break;
	default:
		d_valid = 0;
		return;
	}
	d_valid = 1;
}

/* D holds the content pointed to by n */
void set_d_node_ptr(struct node *n)
{
	memcpy(&d_node, n, sizeof(struct node));
	switch(d_node.op) {
	case T_NAME:
		d_node.op = T_NREF;
		break;
	case T_LABEL:
		d_node.op = T_LBREF;
		break;
	case T_ARGUMENT:
		d_node.value += argbase + frame_len;
		/* Fall through */
	case T_LOCAL:
		d_node.op = T_LREF;
		break;
	default:
		d_valid = 0;
		return;
	}
	d_valid = 1;
}

/* Do we need to check fields by type or will the default filling
   be sufficient ? */
unsigned d_holds_node(struct node *n)
{
	if (d_valid == 0)
		return 0;
	if (d_node.op != n->op)
		return 0;
	if (d_node.val2 != n->val2)
		return 0;
	if (d_node.snum != n->snum)
		return 0;
	if (d_node.value != n->value)
		return 0;
	return 1;
}

void modify_a(uint8_t val)
{
	a_val = val;
	d_valid = 0;
}

void modify_b(uint8_t val)
{
	b_val = val;
	d_valid = 0;
}

/*
 *	Declaration handling. All cases are actually the same, including
 *	typedef (hence the weird typedef syntax)
 */

#include "compiler.h"


unsigned one_typedef(unsigned type, unsigned name)
{
	if (name == 0) {
		error("invalid typedef");
		junk();
		return 0;
	}
	update_symbol_by_name(name, S_TYPEDEF, type);
	return 1;
}

void dotypedef(void)
{
	unsigned type = get_type();
	unsigned name;

	if (type == UNKNOWN)
		type = CINT;

//	while (is_modifier() || is_type_word() || token >= T_SYMBOL || token == T_STAR) {
	while (token != T_SEMICOLON) {
		unsigned utype = type_name_parse(S_NONE, type, &name);
		if (one_typedef(utype, name) == 0)
			return;
		if (!match(T_COMMA))
			break;
	}
	need_semicolon();
}

unsigned one_declaration(register unsigned s, unsigned type, unsigned name, unsigned defstorage)
{
	register struct symbol *sym;
	unsigned offset;

	/* It's quite valid C to just write "int;" but usually dumb except
	   that it's used for struct and union */
	if (name == 0) {
		if (!IS_STRUCT(type))
			warning("useless declaration");
		return 1;
	}
	if ((s == S_AUTO || s == S_REGISTER) && defstorage == S_EXTDEF)
		error("no automatic globals");

	if (IS_FUNCTION(type) && !PTR(type)) {
		if (s == S_EXTDEF || s == S_AUTO)
			s = S_EXTERN;
	}

	if (s == S_REGISTER) {
		offset = target_register(type, S_AUTO);
		if (offset == 0)
			s = S_AUTO;
	}

	/* Do we already have this symbol */
	sym = update_symbol_by_name(name, s, type);

	if (funcbody)
		return 0;

	if (s == S_REGISTER)
		sym->data.offset = offset;
	if (s == S_AUTO)
		sym->data.offset = assign_storage(type, S_AUTO);
	if (s == S_LSTATIC)
		sym->data.offset = ++label_tag;;

	if (voltrack && s != S_AUTO)
		add_volatile(name);

	if (s != S_EXTERN && (PTR(type) || !IS_FUNCTION(type)) && match(T_EQ)) {
		unsigned label = sym->name;
		if (s == S_LSTATIC)
			label = sym->data.offset;
		if (sym->infonext & INITIALIZED)
			error("duplicate initializer");
		sym->infonext |= INITIALIZED;
		if (s >= S_LSTATIC)
		        header(H_DATA, label, target_alignof(type, s));
		initializers(sym, type, s);
		if (s >= S_LSTATIC)
		        footer(H_DATA, label, 0);
	}
	return 1;
}

void declaration(unsigned defstorage)
{
	register unsigned s = get_storage(defstorage);
	unsigned name;
	register unsigned utype;
	unsigned type;

	type = get_type();
	if (type == UNKNOWN)
		type = CINT;

//	while (is_modifier() || is_type_word() || token >= T_SYMBOL || token == T_STAR) {
	while (token != T_SEMICOLON) {
		utype = type_name_parse(s, type, &name);
		if (one_declaration(s, utype, name, defstorage) == 0)
			return;
		if (!match(T_COMMA))
			break;
	}
	need_semicolon();
}

#include "compiler.h"

struct constant {
    unsigned name;
    unsigned value;
};

/*
 *	Enum is really about tables of constant values to substitute for
 *	integer types.
 *	TODO: track the type of the constant ?
 */

static struct constant constant_tab[NUM_CONSTANT];
static struct constant *ctnext = constant_tab;

unsigned find_constant(register unsigned name, unsigned *v)
{
    register struct constant *ct = constant_tab;
    while(ct < ctnext) {
        if (ct->name == name) {
            *v = ct->value;
            return 1;
        }
        ct++;
    }
    return 0;
}

static void insert_constant(unsigned n, unsigned nv)
{
    unsigned v;
    if (find_constant(n, &v)) {
        if (v != nv)
            error("duplicate constant");
        return;
    }
    if (ctnext == &constant_tab[NUM_CONSTANT])
        fatal("too many constants");
    ctnext->name = n;
    ctnext->value = nv;
    ctnext++;
}

/*
 *	Enumerated types. These turn out to be quite simple to parse but
 *	do cause a certain amount of nuisance when type handling elsewhere
 *	because an enum is a complex type but also a simple arithmetic thing.
 */

static unsigned enum_set_base(void)
{
    require(T_EQ);    
    return const_int_expression();
}

/* An enum */
unsigned enum_body(void)
{
    unsigned enum_base = 0;
    unsigned type = CINT;
    unsigned ename;
    register unsigned name;
    register struct symbol *sym = NULL;

    /* Optional */
    ename = symname();

    if (ename)
        sym = find_symbol_by_class(ename, S_ENUM);

    /* TODO: we should if possible pick a range to cover the type. We take
       a rather simplistc approach */
    if (!match(T_LCURLY)) {
        if (sym == NULL) {
            error("unknown enum");
            return CINT;
        }
        return sym->type;
    }
    if (sym) {
        error("duplicate enum");
        junk();
        return CINT;
    }
    while (token != T_RCURLY) {
        name = symname();
        if (name == 0) {
            error("bad enum");
            junk();
            return CINT;
        }
        if (token == T_EQ)
            enum_base = enum_set_base();
        if (enum_base > TARGET_MAX_INT)
            type = UINT;
        /* Enum constants have global scope and are not tied to the enum type. It's
           also possible to refer to a previous one in the next so we must assign as
           we go (ie enum foo { A, B = A + 4 }; is legal */
        insert_constant(name, enum_base++);            
        if (match(T_COMMA))
            continue;
    }
    if (ename)
        update_symbol_by_name(ename, S_ENUM, type);
    /* An enum takes the type needed to hold the things in it. Thus we can
       shortcut all the type stuff and report the underlying type */
    require(T_RCURLY);
    return type;
}

/*
 *	Headers. These blocks carry the structure of the program outside of
 *	the expressions
 */


#include <unistd.h>
#include <stdlib.h>
#include "compiler.h"

void header(unsigned htype, unsigned name, unsigned data)
{
	static struct header h;
	h.h_type = htype;
	h.h_name = name;
	h.h_data = data;

	out_block("%H", 2);	/* For now until it's all headers/expr */
	out_block(&h, sizeof(h));
}

void footer(unsigned htype, unsigned name, unsigned data)
{
	header(htype | H_FOOTER, name, data);
}

void rewrite_header(unsigned long pos, unsigned htype, unsigned name, unsigned data)
{
	unsigned long curr = out_tell();
	out_seek(pos);
	header(htype, name, data);
	out_seek(curr);
}

unsigned long mark_header(void)
{
	return out_tell();
}

/*
 *	Indexed data. We keep various random little vectors attached to
 *	things in order to track stuff like array sizes and struct fields
 *
 *	This manages them
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "compiler.h"

static unsigned idxmem[IDX_SIZE];
static unsigned *idxptr = idxmem;
/*
 *	Simple for now - we may well be able to brk() this pool although
 *	we will have to decide if we fix the pool or the symbol table size..
 */
unsigned *idx_get(unsigned len)
{
    /* len is in words */
    unsigned *p = idxptr;
    idxptr += len;
    if (idxptr >= idxmem + IDX_SIZE)
        fatal("out of index memory");
    return p;
}

unsigned *idx_copy(unsigned *p, unsigned n)
{
    unsigned *r = idx_get(n);
    memcpy(r, p, n * sizeof(unsigned));
    return r;
}

/*
 *	Labels look like symbols except that they don't really behave
 *	like them in terms of scope. Handle them on their own
 */

#include <stdint.h>
#include "compiler.h"

#define L_DECLARED	0x8000

struct label {
    uint16_t name;
    uint16_t line;
};

struct label labels[MAXLABEL];
struct label *labelp;

void init_labels(void)
{
    labelp = labels;
}

static void new_label(unsigned n)
{
    if (labelp == &labels[MAXLABEL])
        fatal("too many goto labels");
    labelp->name = n;
    labelp->line = line_num;
    labelp++;
}

static struct label *find_label(register unsigned n)
{
    register struct label *p = labels;
    n &= 0x7FFF;
    while(p < labelp) {
        if (n == (p->name & 0x7FFF))
            return p;
        p++;
    }
    return NULL;
}

void use_label(unsigned n)
{
    if (find_label(n))
        return;
    new_label(n & 0x7FFF);
}

void add_label(unsigned n)
{
    register struct label *l = find_label(n);
    if (l && (l->name & L_DECLARED))
        error("duplicate label");
    if (l == NULL)
        new_label(n | L_DECLARED);
    else
        l->name |= L_DECLARED;
}

void check_labels(void)
{
    register struct label *p = labels;
    while(p < labelp) {
        if (!(p->name & L_DECLARED))
            errorline(p->line, "unknown label");
        p++;
    }
}

