#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>

#include "compiler.h"

FILE *debug;

unsigned deffunctype;		/* The type of an undeclared function */
unsigned funcbody;		/* Parser global for function body */
unsigned voltrack;		/* Track possible volatiles */
unsigned in_sizeof;		/* Set if we are in sizeof() */
unsigned cputype;		/* So the target specific code can make decisions */
unsigned long cpufeat;		/* CPU feature flags from user for target specific code */

/*
 *	A C program consists of a series of declarations that by default
 *	are external definitions.
 */
static void toplevel(void)
{
	if (token == T_TYPEDEF) {
		next_token();
		dotypedef();
	} else {
		funcbody = 0;
		voltrack = 0;
		target_reginit();
		declaration(S_EXTDEF);
	}
}

/* A function defined by use is taken to be int f(); */
static unsigned functype[2] = {
	1, ELLIPSIS
};

int main(int argc, char *argv[])
{
	if (argc != 3) {
		error("cc1 cpuname features");
		exit(1);
	}
	cputype = atoi(argv[1]);
	cpufeat = atol(argv[2]);
	next_token();
	init_nodes();
	/* A function with no type info returning INT */
	deffunctype = make_function(CINT, functype);
#ifdef DEBUG
	if (argv[1]) {
		debug = fopen(argv[1], "w");
		if (debug == NULL) {
			perror(argv[1]);
			return 255;
		}
	}
#endif
	while (token != T_EOF)
		toplevel();
	/* No write out any uninitialized variables */
	write_bss();
	out_write();
	return errors;
}

/*
 *	C primary objects
 */

#include <stddef.h>
#include <stdio.h>
#include "compiler.h"


/*
 *	The tokenizer has already done the basic conversion work for us and
 *	labelled the type produced. We just need to turn it into a name
 *	and for strings deal with the fact that a string is actually a
 *	literal holding the address of the characters.
 */
struct node *constant_node(void)
{
	struct node *n;
	unsigned label;
	unsigned t;
	int len;

	/* Strings are special */
	label = quoted_string(&len);
	if (label) {
		/* We have a temporary name */
		n = make_label(label);
		if (in_sizeof) {
			unsigned *idx = idx_get(2);
			*idx = 1;	/* 1 dimension */
			idx[1] = len;
#ifdef TARGET_CHAR_UNSIGNED
			n->type = make_array(UCHAR, idx);
#else
			n->type = make_array(CHAR, idx);
#endif
		} else {
			/* The only case the array is seen as a sized array
			   is in sizeof() so for all other cases decay it to
			   a char pointer in advance to save all the extra
			   type tracking  cost */
#ifdef TARGET_CHAR_UNSIGNED
			n->type = PTRTO | UCHAR;
#else
			n->type = PTRTO | CHAR;
#endif
		}
		return n;
	}
	/* Numeric */
	switch (token) {
	case T_INTVAL:
		t = CINT;
		break;
	case T_LONGVAL:
		t = CLONG;
		break;
	case T_UINTVAL:
		t = UINT;
		break;
	case T_ULONGVAL:
		t = ULONG;
		break;
	case T_FLOATVAL:
		t = FLOAT;
		break;
	default:
		error("invalid value");
		t = CINT;
		break;
	}
	n = make_constant(token_value, t);
	next_token();
	return n;
}

/*
 *	A C language primary. This can be one of several things
 *
 *	1.	Another expression in brackets, in which case we recurse
 *	3.	A name
 *	4.	A constant
 */
struct node *primary(void)
{
	struct node *l;
	unsigned func = 0;
	unsigned name;
	unsigned p = 0;

	/* Expression case first.. a bracketed expression is a primary */
	if (match(T_LPAREN)) {
		l = hier0(1);
		require(T_RPAREN);
		return l;
	}
	/* Names or types */
	name = symname();
	if (token == T_LPAREN)
		func = 1;
	if (name) {
		struct symbol *sym = find_symbol(name, 0);
		/* Weird case you can call a function you've not declared. This
		   makes it int f() */
		if (func && sym == NULL) {
			warning("undeclared function prototype");
			sym = update_symbol_by_name(name, S_EXTERN, deffunctype);
		}
		/* You can't size fields and structs by field/struct name without 
		   the type specifier */
		if (sym == NULL) {
			/* Enum... */
			if (find_constant(name, &p) == 0)
				error("unknown symbol");
			return make_constant(p, CINT);
		}
		/* Primary can be followed by operators and the caller handles those */
		return make_symbol(sym);
	}
	/* Not a name - constants or strings */
	return constant_node();
}

/*
 *	Assign offsets in the stack frame (or elsewhere)
 */

#include <stdio.h>
#include "compiler.h"

/* These track which registers are aliases to arguments and must be
   loaded at function entry */
struct symbol *reg_load[NUM_REG + 1];
unsigned reg_offset[NUM_REG + 1];

static unsigned arg_frame;
static unsigned local_frame;
static unsigned local_max;

/*
 *	We will need to deal with alignment rules later
 */

unsigned alloc_room(unsigned *p, unsigned type, unsigned storage)
{
    unsigned s = type_sizeof(type);
    unsigned a = target_alignof(type, storage);

    *p = (*p + a - 1) & ~(a - 1);
    a = *p;
    *p += s;
    return a;
}

unsigned assign_storage(unsigned type, unsigned storage)
{
    unsigned *p = &arg_frame;
    unsigned n;
    if (storage == S_AUTO)
        p = &local_frame;
    n = alloc_room(p, type, storage);
    if (storage == S_AUTO) {
        if (local_frame > local_max)
            local_max = local_frame;
    }
    return n;
}

void mark_storage(unsigned *a, unsigned *b)
{
    *a = arg_frame;
    *b = local_frame;
}

void pop_storage(unsigned *a, unsigned *b)
{
    arg_frame = *a;
    local_frame = *b;
}

void init_storage(void)
{
    arg_frame = 0;
    local_frame = 0;
    local_max = 0;
}

unsigned frame_size(void)
{
    return local_max;
}

unsigned arg_size(void)
{
    return arg_frame;
}

#include <unistd.h>
#include "compiler.h"

unsigned is_storage_word(void)
{
	return (token >= T_AUTO && token <= T_STATIC);
}

unsigned get_storage(unsigned dflt)
{
	unsigned t;
	skip_modifiers();
	if (!is_storage_word())
		return dflt;
	t = token;
	next_token();
	switch (t) {
	case T_AUTO:
		return S_AUTO;
	case T_REGISTER:
		return S_REGISTER;
	case T_STATIC:
		if (dflt == S_AUTO)
			return S_LSTATIC;
		else
			return S_STATIC;
	case T_EXTERN:
		return S_EXTERN;
	}
	/* gcc */
	return 0;
}

/*
 *	Storage I/O - hacks for now
 */

void put_typed_data(struct node *n)
{
	unsigned op = n->op;
	register unsigned t = n->type;
	/* Collapse array types down to their underlying type so the backend
	   can use the correct pointer types on a word/byteptr machine */
	if (IS_ARRAY(t) && PTR(t) == 0)
		t = PTRTO + array_type(t);
	/* Allow for implied casting in the declaration on word machines. For
	   example  "int *x = (int *)charptr;" */
	if (op == T_CAST && PTR(t) && PTR(n->right->type)) {
		n = n->right;
		op = n->op;
	}
	out_block("%[", 2);
	if (op != T_CASELABEL && op != T_PAD && op != T_LABEL &&
		op != T_NAME && op != T_CONSTANT)
		notconst();
	n->type = t;
	out_block(n, sizeof(struct node));
}

void put_padding_data(unsigned space)
{
	register struct node *n = make_constant(space, UINT);
	n->op = T_PAD;
	put_typed_data(n);
	free_node(n);
}

void put_typed_constant(unsigned type, unsigned long value)
{
	struct node *n = make_constant(value, type);
	put_typed_data(n);
	free_node(n);
}

void put_typed_case(unsigned tag, unsigned entry)
{
	register struct node *n = make_constant(tag, PTRTO|VOID);
	n->op = T_CASELABEL;
	n->val2 = entry;
	put_typed_data(n);
	free_node(n);
}

#include "compiler.h"

/*
 *	Struct declarations
 */

static void struct_add_field(struct symbol *sym, unsigned name, unsigned type)
{
    register unsigned *p = sym->data.idx;
    register unsigned n = 0;
    register unsigned *t = p + 2;

    while(n < *p) {
        if (*t == name)
            error("duplicate field");
        t += 3;
        n++;
    }
    *t++ = name;
    *t++ = type;
    (*p)++;
    if (S_STORAGE(sym->infonext) == S_UNION) {
        /* For a union track the largest element size */
        unsigned s = type_sizeof(type);
        *t = 0;
        if (p[1] < s)
            p[1] = s;
    } else {
        /* For a struct allocate fields and track offset */
        *t = alloc_room(p + 1, type, S_STRUCT);
    }
}

static unsigned structdepth;

void struct_declaration(struct symbol *sym)
{
    unsigned name;
    unsigned t;
    unsigned tags[3 * NUM_STRUCT_FIELD + 2];	/* max 30 fields per struct for the moment */
    unsigned nfield = 0;
    unsigned err = 0;
    unsigned ut;

    if (sym->infonext & INITIALIZED)
        error("struct declared twice");
    sym->infonext |= INITIALIZED;

    /* Temporarily, as this can recurse */
    sym->data.idx = tags;

    *tags = 0;		/* No elements */
    tags[1] = 0;	/* Zero space */

    structdepth++;

    if (structdepth == 4)	/* Avoid stack overflows */
        fatal("struct too complex");

    require(T_LCURLY);
    while(token != T_RCURLY) {
        t = get_type();
        if (t == UNKNOWN) {
            badtype();
            junk();
            continue;
        }
        do {
            ut = type_name_parse(S_NONE, t, &name);
            if (nfield == NUM_STRUCT_FIELD) {
                if (err == 0)
                    error("too many struct/union fields");
                err = 1;
            } else {
                struct_add_field(sym, name, ut);
                nfield++;
            }
        } while (match(T_COMMA));
        require(T_SEMICOLON);
    }
    require(T_RCURLY);

    sym->data.idx = idx_copy(tags, 2 + 3 * *tags);

    structdepth--;
}

#include "compiler.h"

/* Will need typing for the largest integral type TODO */
unsigned long switch_table[NUM_SWITCH];
unsigned long *switch_next = switch_table;

/*
 *	When we finish a switch block off we write the table out. We could
 *	do things here like enable binary search but for now we don't and
 *	for some types it's tricky
 *	TODO;
 */
void switch_done(unsigned tag, unsigned long *oldptr, unsigned type)
{
    unsigned count = 0;
    unsigned long *p = oldptr;

    header(H_SWITCHTAB, tag, switch_next - oldptr);
    /* Table */
    while(p < switch_next) {
        put_typed_constant(type, *p++);
        put_typed_case(tag, ++count);
