import re,json,os,collections
from pathlib import Path
from datetime import datetime
import pandas as pd

def mkdir(path):
    # 去除首位空格
    path=path.strip()
    # 去除尾部 \ 符号
    path=path.rstrip("\\")
    path=path.encode('utf-8')
    # 判断路径是否存在
    # 存在     True
    # 不存在   False
    isExists=os.path.exists(path)
    # 判断结果
    if not isExists:
        os.makedirs(path)
        return True
    else:
        # 如果目录存在则不创建，并提示目录已存在
        return False


def find_time(file_path):
    with open (file_path, 'r',encoding='UTF-8') as f:
        lines = f.readlines()
        a = ''
        for line in lines:
            a += line.strip()
    b = a.split("*****")
    res = []
    for post in b:
        post_time = ''.join(re.findall(r"^.*?发表于\s(\d{4}-\d{1,2}-\d{1,2})", post))
        res.append(post_time)
    return res

def filter_time(troll,input_list):
    return_dict = dict(collections.Counter(input_list))
    for i in list(return_dict.keys()):
        if return_dict[i] < 45 or i not in date_list:
            return_dict.pop(i)
        #外野数据量太大，提高筛选标准
        elif troll =='troll' and return_dict[i] < 90:
            return_dict.pop(i)
    if(len(return_dict) <2):
        return None
    else:
        return return_dict

